// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        amount = bound(amount, 2, type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();
        uint256 b = type(uint256).max - amount;
        vm.deal(actor, b);
        bool ok;
        vm.prank(actor);
        try c.deposit{value: b}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
